import React, { useState, useEffect } from "react";
import { BrowserRouter as Router, Routes, Route } from "react-router-dom";
import "./App.css";
import Navbar from "./components/Navbar";
import SecondaryNavbar from "./components/SecondaryNavbar";
import ChatBox from "./components/ChatBox";
import YouTube from "./components/YouTube";
import Wikipedia from "./components/Wikipedia";
import Test from "./components/Test";

const App = () => {
  const [messages, setMessages] = useState([]);
  const [latestQuery, setLatestQuery] = useState("");
  const [topics, setTopics] = useState([]);

  // Load messages & topics from localStorage on app start
  useEffect(() => {
    const savedMessages = JSON.parse(localStorage.getItem("messages")) || [];
    const savedTopics = JSON.parse(localStorage.getItem("topics")) || [];
    setMessages(savedMessages);
    setTopics(savedTopics);
  }, []);

  // Save messages & topics to localStorage when updated
  useEffect(() => {
    localStorage.setItem("messages", JSON.stringify(messages));
  }, [messages]);

  useEffect(() => {
    localStorage.setItem("topics", JSON.stringify(topics));
  }, [topics]);

  return (
    <Router>
      <div className="app-container">
        <SecondaryNavbar />
        <Navbar />

        {/* Routing Setup */}
        <div className="content">
          <Routes>
            <Route path="/" element={<ChatBox messages={messages} setMessages={setMessages} setLatestQuery={setLatestQuery} />} />
            <Route path="/youtube" element={<YouTube latestQuery={latestQuery} />} />
            <Route path="/wikipedia" element={<Wikipedia latestQuery={latestQuery} />} />
            <Route path="/test" element={<Test messages={messages} latestQuery={latestQuery} topics={topics} setTopics={setTopics} />} />
            <Route path="/profile" element={<h1>Profile Page</h1>} />
            <Route path="/dashboard" element={<h1>Dashboard Page</h1>} />
            <Route path="/settings" element={<h1>Settings Page</h1>} />
            <Route path="/logout" element={<h1>Logout Page</h1>} />
          </Routes>
        </div>

        <footer className="footer">
          <p>&copy; 2025 PAT | @Indrajit002</p>
        </footer>
      </div>
    </Router>
  );
};

export default App;
